package com.capo.diarioclase.data.db
import androidx.room.*
@Entity(tableName="sessions") data class SessionEntity(@PrimaryKey val id:String,val pedagogicalDate:String,val level:String?,val state:String,val startedAtEpochMs:Long,val updatedAtEpochMs:Long)
@Entity(tableName="blocks",foreignKeys=[ForeignKey(entity=SessionEntity::class,parentColumns=["id"],childColumns=["sessionId"],onDelete=ForeignKey.CASCADE)],indices=[Index("sessionId")])
data class BlockEntity(@PrimaryKey val id:String,val sessionId:String,val ordinal:Int,val startedAtEpochMs:Long,val endedAtEpochMs:Long?,val closeReason:String?)
@Entity(tableName="audio_segments",foreignKeys=[ForeignKey(entity=BlockEntity::class,parentColumns=["id"],childColumns=["blockId"],onDelete=ForeignKey.CASCADE)],indices=[Index("blockId"),Index(value=["path"],unique=true)])
data class AudioSegmentEntity(@PrimaryKey val id:String,val blockId:String,val ordinal:Int,val path:String,val byteCount:Long,val durationMs:Long,val sha256:String?,val state:String,val transcriptionAttempts:Int=0,val lastTranscriptionFailure:String?=null)
@Entity(tableName="markers",foreignKeys=[ForeignKey(entity=BlockEntity::class,parentColumns=["id"],childColumns=["blockId"],onDelete=ForeignKey.CASCADE)],indices=[Index("sessionId"),Index("blockId")])
data class MarkerEntity(@PrimaryKey val id:String,val sessionId:String,val blockId:String,val absoluteEpochMs:Long,val offsetMs:Long,val type:String,val note:String?)
@Entity(tableName="transcript_spans",foreignKeys=[ForeignKey(entity=AudioSegmentEntity::class,parentColumns=["id"],childColumns=["audioSegmentId"],onDelete=ForeignKey.CASCADE)],indices=[Index("audioSegmentId"),Index("blockId")])
data class TranscriptSpanEntity(@PrimaryKey val id:String,val audioSegmentId:String,val blockId:String,val startMs:Long,val endMs:Long,val text:String,val confidence:Double)
@Entity(tableName="evidence_claims",foreignKeys=[ForeignKey(entity=SessionEntity::class,parentColumns=["id"],childColumns=["sessionId"],onDelete=ForeignKey.CASCADE)],indices=[Index("sessionId"),Index(value=["sessionId","category"])])
data class EvidenceClaimEntity(@PrimaryKey val id:String,val sessionId:String,val category:String,val value:String,val normalizedValue:String,val status:String,val confidence:Double,val origin:String,val blockId:String,val startMs:Long,val endMs:Long,val excerpt:String,val active:Boolean)
@Entity(tableName="diary_drafts",foreignKeys=[ForeignKey(entity=SessionEntity::class,parentColumns=["id"],childColumns=["sessionId"],onDelete=ForeignKey.CASCADE)],indices=[Index("sessionId",unique=true)])
data class DiaryDraftEntity(@PrimaryKey val id:String,val sessionId:String,val mode:String,val topics:String,val activities:String,val pages:String,val exercises:String,val homework:String,val updatedAtEpochMs:Long,val userEdited:Boolean=false)
@Entity(tableName="diary_entries",indices=[Index(value=["sessionId"],unique=true)])
data class DiaryEntryEntity(@PrimaryKey val id:String,val sessionId:String,val pedagogicalDate:String,val level:String?,val topics:String,val activities:String,val pages:String,val completedExercises:String,val homework:String,val approvedAtEpochMs:Long,val updatedAtEpochMs:Long,val temporariesDeleted:Boolean)
@Entity(tableName="app_settings")
data class AppSettingEntity(@PrimaryKey val key:String,val value:String)
data class SessionWithBlocks(@Embedded val session:SessionEntity,@Relation(parentColumn="id",entityColumn="sessionId") val blocks:List<BlockEntity>)
